    public static TFMWorkflowValidation FindValidationClass(TFMWorkflowValidationType _validationType)
    {
        ListEnumerator			lEnum = new SysDictClass(classNum(TFMWorkflowValidation)).extendedBy().getEnumerator();
        TFMWorkflowValidation	validationClass;
        SysDictClass			sdc;

		while (lEnum.moveNext())
        {
            sdc = new SysDictClass(lEnum.current());
            if (!sdc.allowMakeObject())
            {
                continue;
            }
            validationClass = sdc.makeObject();
            if (validationClass.validationType() == _validationType)
            {
                return validationClass;
            }
		}
        return null;
	}

public static boolean allowValidationLevel(TFMWorkflowValidationType _validationType)
{        
    TFMWorkflowValidation	validationClass = TFMWorkflowValidation::FindValidationClass(_validationType);

    if (validationClass)
    {
        return validationClass.isValidationLevelAllowed();
    }
    return false;
}

public static boolean allowValidateEmptyValue(TFMWorkflowValidationType _validationType)
{
    TFMWorkflowValidation	validationClass = TFMWorkflowValidation::FindValidationClass(_validationType);

    if (validationClass)
    {
        return validationClass.isValidateEmptyValueAllowed();
    }
    return false;
}
